-- Fase 28: agregados controlados, health score explicável e assignments persistentes.
create or replace function public.refresh_product_growth_models() returns jsonb language plpgsql security definer set search_path='' as $$declare refreshed integer:=0;opportunities integer:=0;begin
 if current_user not in('service_role','postgres') and not private.is_superadmin() then raise exception 'access denied';end if;
 perform public.process_product_event_queue(500);
 insert into public.product_organization_daily_metrics(organization_id,metric_date,meaningful_actions,active_users,active_stores,orders_processed,support_tickets,failed_payments,features_used,revenue_cents,updated_at)
 select o.id,current_date,count(e.id) filter(where e.event_name in('first_order_received','core_action_performed','feature_used')),count(distinct e.user_id),count(distinct e.store_id),count(e.id) filter(where e.event_name='first_order_received'),count(e.id) filter(where e.event_name='support_ticket_created'),count(e.id) filter(where e.event_name='payment_failed'),coalesce(array_agg(distinct e.properties->>'feature_key') filter(where e.properties ? 'feature_key'),'{}'),coalesce((select sum(i.amount_paid_cents) from public.subscription_invoices i join public.establishments s on s.id=i.establishment_id where s.organization_id=o.id and i.status in('paid','succeeded') and i.created_at::date=current_date),0),now()
 from public.organizations o left join public.product_events e on e.organization_id=o.id and e.occurred_at::date=current_date group by o.id
 on conflict(organization_id,metric_date) do update set meaningful_actions=excluded.meaningful_actions,active_users=excluded.active_users,active_stores=excluded.active_stores,orders_processed=excluded.orders_processed,support_tickets=excluded.support_tickets,failed_payments=excluded.failed_payments,features_used=excluded.features_used,revenue_cents=excluded.revenue_cents,updated_at=now();
 with scores as (
  select o.id,
   least(100,(case when exists(select 1 from public.product_events e where e.organization_id=o.id and e.event_name='store_created') then 20 else 0 end)+(case when exists(select 1 from public.product_events e where e.organization_id=o.id and e.event_name='product_created') then 15 else 0 end)+(case when exists(select 1 from public.product_events e where e.organization_id=o.id and e.event_name='menu_published') then 25 else 0 end)+(case when exists(select 1 from public.product_events e where e.organization_id=o.id and e.event_name='first_order_received') then 40 else 0 end))::numeric activation,
   least(100,(select count(distinct coalesce(e.properties->>'feature_key',e.event_name))*12.5 from public.product_events e where e.organization_id=o.id and e.event_name in('whatsapp_connected','ai_enabled','first_ai_order','first_campaign_created','feature_used')))::numeric adoption,
   least(100,(select count(*)*5 from public.product_events e where e.organization_id=o.id and e.occurred_at>=now()-interval '30 days' and e.event_name in('first_order_received','core_action_performed','feature_used')))::numeric usage,
   greatest(0,100-(select count(*)*10 from public.support_tickets t where t.organization_id=o.id and t.created_at>=now()-interval '30 days' and t.status not in('resolved','closed')))::numeric support,
   case when exists(select 1 from public.subscriptions s where s.organization_id=o.id and s.status in('past_due','unpaid')) then 25 when exists(select 1 from public.subscriptions s where s.organization_id=o.id and s.status='active') then 100 else 60 end::numeric billing,
   coalesce((select max(s.progress_percent) from public.onboarding_sessions s where s.organization_id=o.id),case when o.activated_at is not null then 100 else 0 end)::numeric onboarding,
   (select max(e.occurred_at) from public.product_events e where e.organization_id=o.id) last_activity
  from public.organizations o where o.status<>'deleted' and not o.is_test_organization
 ), totals as(select *,greatest(0,round((activation*.20+adoption*.20+usage*.25+support*.10+billing*.15+onboarding*.10)-(case when last_activity<now()-interval '30 days' then 20 when last_activity<now()-interval '14 days' then 10 else 0 end),2)) total from scores)
 insert into public.customer_health_scores(organization_id,total_score,risk_level,activation_score,adoption_score,usage_score,support_score,billing_score,onboarding_score,explanation,estimated,last_meaningful_activity_at,calculated_at)
 select id,total,case when total>=75 then 'healthy' when total>=55 then 'attention' when total>=30 then 'at_risk' else 'critical' end,activation,adoption,usage,support,billing,onboarding,jsonb_build_object('formula','activation 20%, adoption 20%, usage 25%, support 10%, billing 15%, onboarding 10%','inactivity_penalty',case when last_activity<now()-interval '30 days' then 20 when last_activity<now()-interval '14 days' then 10 else 0 end),true,last_activity,now() from totals
 on conflict(organization_id) do update set total_score=excluded.total_score,risk_level=excluded.risk_level,activation_score=excluded.activation_score,adoption_score=excluded.adoption_score,usage_score=excluded.usage_score,support_score=excluded.support_score,billing_score=excluded.billing_score,onboarding_score=excluded.onboarding_score,explanation=excluded.explanation,estimated=true,last_meaningful_activity_at=excluded.last_meaningful_activity_at,calculated_at=now();
 get diagnostics refreshed=row_count;
 insert into public.growth_opportunities(organization_id,opportunity_type,title,reason,evidence,priority,suggested_action,cooldown_until)
 select h.organization_id,case when h.activation_score<40 then 'activation' else 'retention' end,case when h.activation_score<40 then 'Apoiar ativação' else 'Contato preventivo de Customer Success' end,case when h.activation_score<40 then 'A ativação está incompleta; o cliente ainda não chegou ao primeiro valor.' else 'Risco estimado por queda de uso, suporte ou billing.' end,jsonb_build_object('health_score',h.total_score,'activation_score',h.activation_score,'components',h.explanation),case when h.risk_level='critical' then 95 else 75 end,'Criar tarefa interna e revisar contexto antes de qualquer contato.',now()+interval '14 days'
 from public.customer_health_scores h where (h.risk_level in('at_risk','critical') or h.activation_score<40) and not exists(select 1 from public.growth_opportunities g where g.organization_id=h.organization_id and g.status='open' and g.opportunity_type in('activation','retention'));
 get diagnostics opportunities=row_count;
 insert into public.product_cohort_metrics(cohort_month,dimension_key,dimension_value,age_days,cohort_size,retained_organizations,retention_percent,calculated_at)
 select date_trunc('month',o.created_at)::date,'all','all',d.age,count(*) filter(where now()-o.created_at>=make_interval(days=>d.age)),count(*) filter(where now()-o.created_at>=make_interval(days=>d.age) and exists(select 1 from public.product_events e where e.organization_id=o.id and e.occurred_at::date=o.created_at::date+d.age)),case when count(*) filter(where now()-o.created_at>=make_interval(days=>d.age))=0 then 0 else round(100.0*count(*) filter(where now()-o.created_at>=make_interval(days=>d.age) and exists(select 1 from public.product_events e where e.organization_id=o.id and e.occurred_at::date=o.created_at::date+d.age))/count(*) filter(where now()-o.created_at>=make_interval(days=>d.age)),2) end,now()
 from public.organizations o cross join (values(1),(7),(30),(60),(90)) d(age) where not o.is_test_organization group by date_trunc('month',o.created_at)::date,d.age
 on conflict(cohort_month,dimension_key,dimension_value,age_days) do update set cohort_size=excluded.cohort_size,retained_organizations=excluded.retained_organizations,retention_percent=excluded.retention_percent,calculated_at=now();
 return jsonb_build_object('health_scores',refreshed,'opportunities_created',opportunities,'refreshed_at',now());end$$;
revoke all on function public.refresh_product_growth_models() from public,anon,authenticated;grant execute on function public.refresh_product_growth_models() to service_role;

create or replace function public.assign_product_experiment(requested_experiment_key text,requested_organization_id uuid,requested_user_id uuid default null) returns jsonb language plpgsql security definer set search_path='' as $$declare exp public.product_experiments;assignment text;bucket integer;variant public.product_experiment_variants;result public.product_experiment_assignments;begin
 select * into exp from public.product_experiments where experiment_key=requested_experiment_key and status='running' and now() between coalesce(start_at,'-infinity') and coalesce(end_at,'infinity');if exp.id is null then return null;end if;
 if (select auth.uid()) is null or not exists(select 1 from public.organization_members m where m.organization_id=requested_organization_id and m.user_id=(select auth.uid()) and m.active) then raise exception 'access denied';end if;
 assignment:=case when exp.assignment_level='organization' then requested_organization_id::text else coalesce(requested_user_id,(select auth.uid()))::text end;
 select a.* into result from public.product_experiment_assignments a where a.experiment_id=exp.id and a.assignment_key=assignment;if result.id is not null then select * into variant from public.product_experiment_variants where id=result.variant_id;return jsonb_build_object('experiment',exp.experiment_key,'variant',variant.variant_key,'persisted',true);end if;
 bucket:=abs(hashtextextended(exp.experiment_key||':'||assignment,0)%100);select v.* into variant from public.product_experiment_variants v where v.experiment_id=exp.id and bucket<(select sum(v2.weight) from public.product_experiment_variants v2 where v2.experiment_id=exp.id and v2.variant_key<=v.variant_key) order by v.variant_key limit 1;
 insert into public.product_experiment_assignments(experiment_id,variant_id,organization_id,user_id,assignment_key) values(exp.id,variant.id,requested_organization_id,case when exp.assignment_level='user' then coalesce(requested_user_id,(select auth.uid())) else null end,assignment);return jsonb_build_object('experiment',exp.experiment_key,'variant',variant.variant_key,'persisted',false);end$$;
revoke all on function public.assign_product_experiment(text,uuid,uuid) from public,anon;grant execute on function public.assign_product_experiment(text,uuid,uuid) to authenticated;

create or replace function public.get_saas_lifecycle_messages(requested_organization_id uuid) returns jsonb language sql stable security definer set search_path='' as $$select coalesce(jsonb_agg(jsonb_build_object('campaign_id',c.id,'name',c.name,'type',c.message_type,'content',c.content,'stage',c.lifecycle_stage)),'[]'::jsonb) from public.saas_lifecycle_campaigns c where c.status='active' and exists(select 1 from public.organization_members m where m.organization_id=requested_organization_id and m.user_id=(select auth.uid()) and m.active) and (not c.requires_consent or coalesce((select analytics_enabled from public.organizations where id=requested_organization_id),false)) and (c.targeting_rules->'plan_codes' is null or exists(select 1 from public.subscriptions s join public.plans p on p.id=s.plan_id where s.organization_id=requested_organization_id and p.code in(select jsonb_array_elements_text(c.targeting_rules->'plan_codes')))) and (select count(*) from public.saas_lifecycle_deliveries d where d.campaign_id=c.id and d.organization_id=requested_organization_id and d.assigned_at>=now()-make_interval(days=>c.frequency_window_days) and d.status in('shown','clicked','converted'))<c.frequency_cap and not exists(select 1 from public.saas_lifecycle_deliveries d where d.campaign_id=c.id and d.organization_id=requested_organization_id and d.status='dismissed')$$;
revoke all on function public.get_saas_lifecycle_messages(uuid) from public,anon;grant execute on function public.get_saas_lifecycle_messages(uuid) to authenticated;
